import{_ as e,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Создание CMS-компонентов - October CMS - 3.x","titleTemplate":false,"description":"Расширение CMS пользовательскими компонентами.","frontmatter":{"subtitle":"Расширение CMS пользовательскими компонентами."},"headers":[{"level":2,"title":"Определение класса компонента","slug":"определение-класса-компонента","link":"#определение-класса-компонента","children":[{"level":3,"title":"Регистрация компонента","slug":"регистрация-компонента","link":"#регистрация-компонента","children":[]}]},{"level":2,"title":"Свойства компонента","slug":"своиства-компонента","link":"#своиства-компонента","children":[]},{"level":2,"title":"Параметры маршрутизации","slug":"параметры-маршрутизации","link":"#параметры-маршрутизации","children":[]},{"level":2,"title":"Обработка цикла выполнения страницы","slug":"обработка-цикла-выполнения-страницы","link":"#обработка-цикла-выполнения-страницы","children":[{"level":3,"title":"Обработчики жизненного цикла выполнения страницы","slug":"обработчики-жизненного-цикла-выполнения-страницы","link":"#обработчики-жизненного-цикла-выполнения-страницы","children":[]},{"level":3,"title":"Инициализация компонента","slug":"инициализация-компонента","link":"#инициализация-компонента","children":[]},{"level":3,"title":"Остановка с ответом","slug":"остановка-с-ответом","link":"#остановка-с-ответом","children":[]}]},{"level":2,"title":"AJAX-обработчики","slug":"ajax-обработчики","link":"#ajax-обработчики","children":[]},{"level":2,"title":"Разметка по умолчанию","slug":"разметка-по-умолчанию","link":"#разметка-по-умолчанию","children":[]},{"level":2,"title":"Частичные представления компонента","slug":"частичные-представления-компонента","link":"#частичные-представления-компонента","children":[{"level":3,"title":"Ссылка на «self»","slug":"ссылка-на-«self»","link":"#ссылка-на-«self»","children":[]},{"level":3,"title":"Уникальный идентификатор","slug":"уникальныи-идентификатор","link":"#уникальныи-идентификатор","children":[]}]},{"level":2,"title":"Рендеринг частичных представлений из кода","slug":"рендеринг-частичных-представлении-из-кода","link":"#рендеринг-частичных-представлении-из-кода","children":[]},{"level":2,"title":"Внедрение ресурсов страницы с помощью компонентов","slug":"внедрение-ресурсов-страницы-с-помощью-компонентов","link":"#внедрение-ресурсов-страницы-с-помощью-компонентов","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/extend/cms-components.md","filePath":"3.x/ru/extend/cms-components.md"}'),u={name:"3.x/ru/extend/cms-components.md"};function r(k,n,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"Создание CMS-компонентов",-1)),a(p),n[1]||(n[1]=i(`<p>Файлы и директории компонентов находятся в поддиректории <strong>components</strong> директории плагина. Каждый компонент имеет PHP-файл, определяющий класс компонента, и необязательную директорию частичных представлений компонента. Имя директории частичных представлений совпадает с именем класса компонента в нижнем регистре. Пример структуры директории компонента:</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── <code>components</code>
|           |   ├── blogposts  <em>← Директория частичных представлений</em>
|           |   |   └── default.htm  <em>← Разметка по умолчанию (необязательно)</em>
|           |   └── BlogPosts.php  <em>← Класс компонента</em>
|           └── Plugin.php</p>
</code></pre><p>Компоненты должны быть <a href="./../extend/extending.html">зарегистрированы в файле регистрации плагина</a> с помощью метода <code>registerComponents</code>. Компоненты могут быть настроены с помощью свойств и их <a href="./../element/inspector-types.html">определений типов Inspector</a>.</p><h2 id="определение-класса-компонента"><a href="#определение-класса-компонента" class="header-anchor">#</a> Определение класса компонента</h2><p>Команда <code>create:component</code> создаёт новый класс компонента и представление компонента по умолчанию. Первый аргумент указывает имя автора и плагина. Второй аргумент указывает имя класса компонента.</p><div class="language-bash extra-class"><pre class="language-bash"><code>php artisan create:component Acme.Blog BlogPosts
</code></pre></div><p>Файл класса компонента определяет функциональность и свойства компонента. Имя файла класса компонента должно совпадать с именем класса компонента. Классы компонентов должны наследовать класс <code>Cms\\Classes\\ComponentBase</code>. Компонент из следующего примера должен быть определён в файле <strong>plugins/acme/blog/components/BlogPosts.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">BlogPosts</span> <span class="token keyword">extends</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Cms<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ComponentBase</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">componentDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Blog Posts&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Displays a collection of blog posts.&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;icon&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;icon-puzzle-piece&#39;</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * posts becomes available on the page as {{ component.posts }}
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">posts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;First Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Second Post&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Third Post&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Метод <code>componentDetails</code> является обязательным. Метод должен возвращать массив с двумя ключами: <code>name</code> и <code>description</code>. Имя и описание отображаются в пользовательском интерфейсе панели управления CMS.</p><p>Когда этот <a href="./../cms/themes/components.html">компонент прикреплён к странице или макету</a>, свойства и методы класса становятся доступными на странице через переменную компонента, имя которой совпадает с коротким именем компонента или псевдонимом. Например, если компонент BlogPost из предыдущего примера определён на странице с его коротким именем:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPosts</span><span class="token punctuation">]</span></span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
</code></pre></div><p>Вы сможете обращаться к его методу <code>posts</code> через переменную <code>blogPosts</code>. Обратите внимание, что Twig поддерживает нотацию свойств для методов, поэтому вам не нужно использовать скобки.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> blogPosts<span class="token punctuation">.</span>posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="регистрация-компонента"><a href="#регистрация-компонента" class="header-anchor">#</a> Регистрация компонента</h3><p>Компоненты должны быть зарегистрированы путём переопределения метода <code>registerComponents</code> в <a href="./../extend/extending.html">файле регистрации плагина</a>. Это сообщает CMS о компоненте и предоставляет <strong>короткое имя</strong> для его использования. Пример регистрации компонента:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerComponents</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Demo<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>Todo</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;demoTodo&#39;</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Это зарегистрирует класс компонента Todo с псевдонимом по умолчанию <strong>demoTodo</strong>. Более подробная информация об использовании компонентов находится в <a href="./../cms/themes/components.html">статье о CMS-компонентах</a>.</p><h2 id="своиства-компонента"><a href="#своиства-компонента" class="header-anchor">#</a> Свойства компонента</h2><p>При добавлении компонента на страницу или в макет вы можете настроить его с помощью свойств. Свойства определяются методом <code>defineProperties</code> класса компонента. В следующем примере показано, как определить свойство компонента с типом Inspector <strong>string</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">defineProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;maxItems&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;title&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Max items&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;description&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The most amount of todo items allowed&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;default&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">10</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;type&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;string&#39;</span><span class="token punctuation">,</span>
            <span class="token string single-quoted-string">&#39;validation&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;regex&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                    <span class="token string single-quoted-string">&#39;message&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;The Max Items property can contain only numeric symbols.&#39;</span><span class="token punctuation">,</span>
                    <span class="token string single-quoted-string">&#39;pattern&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;^[0-9]+$&#39;</span>
                <span class="token punctuation">]</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Метод должен возвращать массив с ключами свойств в качестве индексов и параметрами свойств в качестве значений. Ключи свойств используются для доступа к значениям свойств компонента внутри класса компонента.</p><div class="custom-block tip"><p>Параметры свойств и доступные типы описаны в <a href="./../element/inspector-types.html">статье о типах Inspector</a>.</p></div><p>Внутри компонента вы можете прочитать значение свойства с помощью метода <code>property</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если значение свойства не определено, вы можете передать значение по умолчанию вторым параметром метода <code>property</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">,</span> <span class="token number">6</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Вы также можете загрузить все свойства как массив:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$properties</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getProperties</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Для доступа к свойству из Twig-частичных представлений компонента используйте переменную <code>__SELF__</code>, которая ссылается на объект компонента:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> __SELF__<span class="token punctuation">.</span>property<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>maxItems<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="параметры-маршрутизации"><a href="#параметры-маршрутизации" class="header-anchor">#</a> Параметры маршрутизации</h2><p>Компоненты могут напрямую обращаться к значениям параметров маршрутизации, определённым в <a href="./../cms/themes/pages.html">URL страницы</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns the URL segment value, eg: /page/:post_id</span>
<span class="token variable">$postId</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">param</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;post_id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В некоторых случаях свойство компонента может быть жёстко заданным значением или ссылаться на значение из URL. В этом примере с жёстко заданным значением используется запись блога с идентификатором <code>2</code>:</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/hard-coded-page</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">2</span>&quot;</span>
</code></pre></div><p>Альтернативно значение может быть динамически получено из URL страницы с помощью <a href="./../cms/themes/components.html">внешнего значения свойства компонента</a>.</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/blog/:my_custom_parameter</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">blogPost</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">id</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">{{ :my_custom_parameter }}</span>&quot;</span>
</code></pre></div><p>В обоих случаях значение можно получить с помощью метода <code>property</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Если вам нужно получить имя параметра маршрутизации:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Returns &quot;my_custom_parameter&quot;</span>
<span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">paramName</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="обработка-цикла-выполнения-страницы"><a href="#обработка-цикла-выполнения-страницы" class="header-anchor">#</a> Обработка цикла выполнения страницы</h2><p>Компоненты могут участвовать в событиях цикла выполнения страницы, переопределяя метод <code>onRun</code> в классе компонента. CMS-контроллер выполняет этот метод каждый раз при загрузке страницы или макета. Внутри метода вы можете внедрять переменные в среду Twig через свойство <code>page</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This code will be executed when the page or layout is</span>
    <span class="token comment">// loaded and the component is attached to it.</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;value&#39;</span><span class="token punctuation">;</span> <span class="token comment">// Inject some variable to the page</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="обработчики-жизненного-цикла-выполнения-страницы"><a href="#обработчики-жизненного-цикла-выполнения-страницы" class="header-anchor">#</a> Обработчики жизненного цикла выполнения страницы</h3><p>При загрузке страницы October выполняет функции-обработчики, которые могут быть определены в PHP-секции макета и страницы, а также в классах компонентов. Последовательность выполнения обработчиков следующая.</p><ol><li>Функция <code>onInit()</code> макета.</li><li>Функция <code>onInit()</code> страницы.</li><li>Функция <code>onStart()</code> макета.</li><li>Метод <code>onRun()</code> компонентов макета.</li><li>Функция <code>onBeforePageStart()</code> макета.</li><li>Функция <code>onStart()</code> страницы.</li><li>Метод <code>onRun()</code> компонентов страницы.</li><li>Функция <code>onEnd()</code> страницы.</li><li>Функция <code>onEnd()</code> макета.</li></ol><h3 id="инициализация-компонента"><a href="#инициализация-компонента" class="header-anchor">#</a> Инициализация компонента</h3><p>Иногда вам может потребоваться выполнить код в момент первого создания экземпляра класса компонента. Вы можете переопределить метод <code>init</code> в классе компонента для обработки любой логики инициализации — он выполнится до AJAX-обработчиков и до жизненного цикла выполнения страницы. Например, этот метод может использоваться для динамического прикрепления другого компонента к странице.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">init</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addComponent</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Components<span class="token punctuation">\\</span>BlogPosts</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;blogPosts&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="остановка-с-ответом"><a href="#остановка-с-ответом" class="header-anchor">#</a> Остановка с ответом</h3><p>Как и все методы в <a href="./../cms/themes/layouts.html">жизненном цикле выполнения макета</a>, если метод <code>onRun</code> компонента возвращает значение, цикл останавливается в этой точке и ответ возвращается в браузер. Здесь мы возвращаем сообщение об отказе в доступе с помощью фасада <code>Response</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Access denied!&#39;</span><span class="token punctuation">,</span> <span class="token number">403</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Вы также можете вернуть ответ 404 из метода <code>onRun</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token constant boolean">true</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">setStatusCode</span><span class="token punctuation">(</span><span class="token number">404</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">controller</span><span class="token operator">-&gt;</span><span class="token function">run</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;404&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="ajax-обработчики"><a href="#ajax-обработчики" class="header-anchor">#</a> AJAX-обработчики</h2><p>Компоненты могут содержать AJAX-обработчики событий. Они определяются в классе компонента точно так же, как в <a href="./../cms/ajax/handlers.html">коде страницы или макета</a>. Пример метода AJAX-обработчика, определённого в классе компонента:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onAddItem</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$value1</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$value2</span> <span class="token operator">=</span> <span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$value1</span> <span class="token operator">+</span> <span class="token variable">$value2</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Если псевдоним этого компонента — <em>demoTodo</em>, к обработчику можно обратиться как <code>demoTodo::onAddItem</code>. Подробнее об использовании AJAX с компонентами см. в <a href="./../cms/ajax/handlers.html">статье об AJAX-обработчиках</a>.</p><h2 id="разметка-по-умолчанию"><a href="#разметка-по-умолчанию" class="header-anchor">#</a> Разметка по умолчанию</h2><p>Все компоненты могут поставляться с разметкой по умолчанию, которая используется при включении компонента на страницу тегом <code>{% component %}</code>, хотя это необязательно. Разметка по умолчанию хранится в <strong>директории частичных представлений компонента</strong>, имя которой совпадает с именем класса компонента в нижнем регистре.</p><p>Разметка по умолчанию компонента должна быть размещена в файле <strong>default.htm</strong>. Например, разметка по умолчанию компонента Demo ToDo определена в файле <strong>/plugins/october/demo/components/todo/default.htm</strong>. Затем она может быть вставлена в любое место страницы тегом <code>{% component %}</code>:</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">url</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">/todo</span>&quot;</span>

<span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">demoTodo</span><span class="token punctuation">]</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Разметка по умолчанию также может принимать параметры, переопределяющие свойства компонента на момент рендеринга.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> maxItems<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>7<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Эти свойства не будут доступны в методе <code>onRun</code>, поскольку они устанавливаются после завершения цикла страницы. Вместо этого они могут быть обработаны путём переопределения метода <code>onRender</code> в классе компонента. CMS-контроллер выполняет этот метод перед рендерингом разметки по умолчанию.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This code will be executed before the default component</span>
    <span class="token comment">// markup is rendered on the page or layout.</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">page</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;var&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;Maximum items allowed: &#39;</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">property</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;maxItems&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="частичные-представления-компонента"><a href="#частичные-представления-компонента" class="header-anchor">#</a> Частичные представления компонента</h2><p>В дополнение к разметке по умолчанию компоненты также могут предоставлять дополнительные частичные представления, которые могут использоваться на фронтенде или внутри самой разметки по умолчанию. Если компонент Demo ToDo имел бы частичное представление <strong>pagination</strong>, оно находилось бы в <strong>/plugins/october/demo/components/todo/pagination.htm</strong> и отображалось на странице с помощью:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo::pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Существует упрощённый контекстный метод. При вызове внутри частичного представления компонента он будет ссылаться непосредственно на себя. При вызове внутри частичного представления темы он просканирует все компоненты, используемые на странице/макете, на наличие совпадающего имени и использует его.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@pagination<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Несколько компонентов могут совместно использовать частичные представления, разместив файл в директории <strong>components/partials</strong>. Частичные представления из этой директории используются как запасной вариант, когда обычное частичное представление компонента не найдено. Например, общее частичное представление в <strong>/plugins/acme/blog/components/partials/shared.htm</strong> может быть отображено на странице любым компонентом с помощью:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>@shared<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="ссылка-на-«self»"><a href="#ссылка-на-«self»" class="header-anchor">#</a> Ссылка на «self»</h3><p>Компоненты могут ссылаться на себя внутри своих частичных представлений с помощью переменной <code>__SELF__</code>. По умолчанию она возвращает <a href="./../cms/themes/components.html">короткое имя или псевдоним компонента</a>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token delimiter punctuation">}}</span></span>::onEventHandler<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    [...]
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Компоненты также могут ссылаться на собственные свойства.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> item <span class="token operator">in</span> __SELF__<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> item <span class="token delimiter punctuation">}}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Если внутри частичного представления компонента нужно отрендерить другое частичное представление компонента, конкатенируйте переменную <code>__SELF__</code> с именем частичного представления:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> __SELF__<span class="token operator">~</span><span class="token string"><span class="token punctuation">&quot;</span>::screenshot-list<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="уникальныи-идентификатор"><a href="#уникальныи-идентификатор" class="header-anchor">#</a> Уникальный идентификатор</h3><p>Если идентичный компонент вызывается дважды на одной странице, свойство <code>id</code> может использоваться для ссылки на каждый экземпляр.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span>__SELF__<span class="token punctuation">.</span>id<span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>ID уникален при каждом отображении компонента.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token comment">&lt;!-- ID: demoTodo527c532e9161b --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>

<span class="token comment">&lt;!-- ID: demoTodo527c532ec4c33 --&gt;</span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&#39;</span>demoTodo<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="рендеринг-частичных-представлении-из-кода"><a href="#рендеринг-частичных-представлении-из-кода" class="header-anchor">#</a> Рендеринг частичных представлений из кода</h2><p>Вы можете программно рендерить частичные представления компонента внутри PHP-кода с помощью метода <code>renderPartial</code>. Метод проверит наличие частичного представления с именем <code>component-partial.htm</code> в компоненте и вернёт результат как строку. Второй параметр используется для передачи переменных представления. Та же логика разрешения путей применяется при рендеринге частичного представления компонента в PHP, как и в Twig; используйте префикс <code>@</code> для ссылки на частичные представления внутри самого компонента.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;John Smith&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Например, для рендеринга частичного представления в ответ на <a href="./../cms/ajax/handlers.html">AJAX-обработчик</a>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onGetTemplate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;#someDiv&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@component-partial.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Другой пример — переопределение всего ответа страницы путём возврата значения из цикла выполнения страницы <code>onRun</code>. Этот код конкретно вернёт XML-ответ с помощью фасада <code>Response</code>:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$content</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">renderPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;@default.htm&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Response</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token variable">$content</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">header</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Content-Type&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;text/xml&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="внедрение-ресурсов-страницы-с-помощью-компонентов"><a href="#внедрение-ресурсов-страницы-с-помощью-компонентов" class="header-anchor">#</a> Внедрение ресурсов страницы с помощью компонентов</h2><p>Компоненты могут внедрять ресурсы (CSS и JavaScript файлы) на страницы или макеты, к которым они прикреплены. Используйте методы контроллера <code>addCss</code> и <code>addJs</code> для добавления ресурсов в CMS-контроллеры. Это можно сделать в методе <code>onRun</code> компонента.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Если путь, указанный в аргументе методов <code>addCss</code> и <code>addJs</code>, начинается со слэша (<code>/</code>), он будет относительным к корню сайта. Если путь к ресурсу не начинается со слэша, он относителен к директории компонента.</p><p>Методы <code>addCss</code> и <code>addJs</code> принимают второй аргумент, определяющий атрибуты внедряемого ресурса в виде массива.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onRun</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">addJs</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/plugins/acme/blog/assets/javascript/blog-controls.js&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;defer&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../element/inspector-types.html">Типы Inspector</a></li></ul></div>`,101))])}const w=e(u,[["render",r]]);export{f as __pageData,w as default};
